function genericCourse(skill: string): Cat {
  return {
    course: `${skill} — Complete Course (Coursera / Udemy / freeCodeCamp)`,
    duration: "3-4 weeks",
    level: "Beginner to Intermediate",
    topics: [
      `Core fundamentals of ${skill}`,
      `Hands-on practice with ${skill}`,
      `Real-world project using ${skill}`,
      "Portfolio project & interview prep",
    ],
  };
}

function buildWeekPlan(skill: string, duration: string, topics: string[]): string[] {
  const weeks = parseInt(duration) || 4;
  const plan: string[] = [];
  for (let i = 0; i < Math.min(weeks, 6); i++) {
    const topic = topics[i % topics.length];
    plan.push(`Week ${i + 1}: ${topic} — 5-7 hrs study + hands-on exercises`);
  }
  plan.push(`Final week: Build & deploy a portfolio project using ${skill}; update resume with GitHub link`);
  return plan;
}

function buildInterviewQuestions(
  jobTitle: string,
  skillsPresent: string[],
  missingSkills: string[],
  jdSkills: string[]
): InterviewQuestion[] {
  const qs: InterviewQuestion[] = [];
  const techSkills = [...new Set([...jdSkills.slice(0, 6), ...missingSkills.slice(0, 4)])];
  for (const s of techSkills.slice(0, 6)) {
    qs.push({
      type: "Technical",
      question: `Explain the core concepts of ${s} and how you would apply them in a ${jobTitle} role.`,
      answer: `Start with a crisp definition of ${s}, then cover 2-3 key concepts (e.g., fundamentals, common use cases, and trade-offs). Illustrate with a small example from your own project or coursework, and close by explaining how ${s} solves a real problem in the ${jobTitle} context. Mention tools, best practices, and one common pitfall to avoid.`,
    });
  }
  const present = skillsPresent.slice(0, 3);
  for (const s of present) {
    qs.push({
      type: "Technical",
      question: `Describe a project where you used ${s}. What challenges did you face and how did you solve them?`,
      answer: `Use the STAR format: Situation (project goal), Task (your responsibility), Action (specific steps you took with ${s} — tools, decisions, code), Result (quantified outcome like performance gain, accuracy, or user impact). Keep it under 2 minutes and end with what you learned.`,
    });
  }
  qs.push({
    type: "HR",
    question: `Tell me about yourself and why you are a good fit for the ${jobTitle} role.`,
    answer: `Structure: (1) Present — current role/education and key skills (${skillsPresent.slice(0, 3).join(", ") || "your core skills"}). (2) Past — one achievement that shows relevant experience. (3) Future — why this ${jobTitle} role excites you and how you plan to grow. Keep it to 60-90 seconds and connect every point to the job description.`,
  });
  qs.push({
    type: "HR",
    question: "What are your strengths and one area you are actively improving?",
    answer: "Pick a genuine strength backed by evidence (e.g., \"I consistently deliver projects on time — in my last project I shipped X in Y weeks\"). For the improvement area, choose a skill from your missing list, explain the concrete steps you are taking (course, project, timeline), and show progress. This turns a weakness into proof of growth mindset.",
  });
  qs.push({
    type: "Behavioral",
    question: "Describe a time you faced a difficult problem. How did you approach it?",
    answer: "Use STAR: describe the problem context briefly, explain your systematic approach (breakdown, hypotheses, experiments), the actions you took, and the measurable result. Emphasize structured thinking, collaboration, and what you would do differently next time.",
  });
  qs.push({
    type: "Behavioral",
    question: "How do you handle tight deadlines and competing priorities?",
    answer: "Explain your prioritization framework (e.g., impact vs. urgency, MoSCoW), communication habits (early flagging, daily updates), and a concrete example where you delivered under pressure. Mention tools you use (Kanban, time-blocking) and how you protect quality while moving fast.",
  });
  qs.push({
    type: "HR",
    question: "Where do you see yourself in 2-3 years, and how does this role fit your plan?",
    answer: `Connect your growth to the company's trajectory: mastering the core stack (${jdSkills.slice(0, 3).join(", ") || "role skills"}), taking ownership of larger projects, mentoring juniors, and growing toward senior responsibilities. Show that this role is a deliberate step in your career, not just a job.`,
  });
  qs.push({
    type: "Technical",
    question: "How would you approach learning a new tool or technology required for this role?",
    answer: "Describe a repeatable learning loop: (1) fundamentals via docs/course, (2) small hands-on exercises, (3) build a mini-project, (4) apply it in real work and teach it to the team. Give a recent example — e.g., how you picked up a new library or framework — and the outcome.",
  });
  return qs.slice(0, 12);
}

export function analyzeResume(resumeText: string, jobDescription: string, jobTitle: string): AnalysisResult {
  const resumeTokens = tokenize(resumeText);
  const jdTokens = tokenize(jobDescription);
  const resumeVec = tfidfVector(resumeTokens);
  const jdVec = tfidfVector(jdTokens);
  const cosine = cosineSimilarity(resumeVec, jdVec);
  const resumeSkills = extractSkills(resumeText);
  const jdSkills = extractSkills(jobDescription);
  const skillsPresent = jdSkills.filter((s) => resumeSkills.includes(s));
  const missingSkills = jdSkills.filter((s) => !resumeSkills.includes(s));
  const jdUnique = new Set(jdTokens);
  const resumeSet = new Set(resumeTokens);
  let overlap = 0;
  for (const t of jdUnique) if (resumeSet.has(t)) overlap++;
  const keywordOverlap = jdUnique.size > 0 ? overlap / jdUnique.size : 0;
  const skillsCoverage = jdSkills.length > 0 ? skillsPresent.length / jdSkills.length : 0;
  let matchScore = Math.round((cosine * 0.45 + keywordOverlap * 0.25 + skillsCoverage * 0.3) * 100);
  if (cosine > 0) {
    const scaled = Math.round(Math.min(97, 35 + cosine * 140 + skillsCoverage * 18 + keywordOverlap * 10));
    matchScore = Math.max(matchScore, Math.min(scaled, 97));
  }
  matchScore = Math.max(5, Math.min(97, matchScore));
  const lower = resumeText.toLowerCase();
  const hasEmail = /[\w.+-]+@[\w-]+\.[\w.]+/.test(resumeText);
  const hasPhone = /(\+?\d[\d\s\-()]{7,}\d)/.test(resumeText);
  const hasLinkedIn = lower.includes("linkedin");
  const hasGithub = lower.includes("github");
  const hasSummary = lower.includes("summary") || lower.includes("objective") || lower.includes("profile");
  const hasExperience = lower.includes("experience") || lower.includes("employment");
  const hasEducation = lower.includes("education") || lower.includes("degree") || lower.includes("b.tech") || lower.includes("btech") || lower.includes("mca") || lower.includes("bca") || lower.includes("m.tech") || lower.includes("bachelor") || lower.includes("master");
  const hasProjects = lower.includes("project");
  const hasSkillsSection = lower.includes("skill") || lower.includes("technical skills") || lower.includes("core competencies");
  const actionVerbCount = ACTION_VERBS.filter((v) => lower.includes(v)).length;
  const quantified = (resumeText.match(/\d+\s?(%|percent|x|lakh|k\b|\+)/gi) || []).length;
  const wordCount = resumeText.trim().split(/\s+/).filter(Boolean).length;
  const expYearsMatch = resumeText.match(/(\d+(\.\d+)?)\s*\+?\s*years?/gi) || [];
  const expYears = expYearsMatch.length > 0 ? Math.max(...expYearsMatch.map((m) => parseFloat(m) || 0)) : 0;
  let ats = 0;
  ats += Math.min(30, skillsCoverage * 30);
  ats += Math.min(20, keywordOverlap * 20);
  const formatChecks = [hasEmail, hasPhone, hasLinkedIn || hasGithub, hasSummary, hasExperience, hasEducation, hasProjects, hasSkillsSection];
  ats += Math.round((formatChecks.filter(Boolean).length / formatChecks.length) * 25);
  ats += Math.min(15, actionVerbCount * 1.5);
  ats += Math.min(10, quantified * 2 + (expYears > 0 ? 3 : 0));
  const atsScore = Math.max(8, Math.min(98, Math.round(ats)));
  const strengths: string[] = [];
  if (skillsPresent.length >= 3) strengths.push(`Strong overlap: ${skillsPresent.length} required skills found (${skillsPresent.slice(0, 5).join(", ")}${skillsPresent.length > 5 ? "…" : ""}).`);
  else if (skillsPresent.length > 0) strengths.push(`Found ${skillsPresent.length} matching skill(s): ${skillsPresent.join(", ")}.`);
  if (hasEmail && hasPhone) strengths.push("Contact details (email & phone) are present — recruiters can reach you easily.");
  if (hasLinkedIn || hasGithub) strengths.push("Includes LinkedIn/GitHub links — boosts credibility and lets recruiters verify your work.");
  if (hasExperience && hasProjects) strengths.push("Both experience and project sections are present — shows practical, hands-on work.");
  if (actionVerbCount >= 5) strengths.push(`Uses strong action verbs (${actionVerbCount} found) — makes achievements sound impactful.`);
  if (quantified >= 2) strengths.push(`Includes quantified achievements (${quantified} metrics found) — numbers make impact measurable.`);
  if (hasEducation) strengths.push("Education section is clearly present.");
  if (hasSkillsSection) strengths.push("Dedicated skills section makes scanning easy for ATS parsers.");
  if (wordCount >= 300 && wordCount <= 900) strengths.push(`Resume length is ideal (${wordCount} words) — concise yet complete.`);
  if (strengths.length === 0) strengths.push("Resume contains readable text that the parser could extract successfully.");
  const weaknesses: string[] = [];
  if (missingSkills.length > 0) weaknesses.push(`Missing ${missingSkills.length} key skill(s) required by the job: ${missingSkills.slice(0, 6).join(", ")}${missingSkills.length > 6 ? "…" : ""}.`);
  if (!hasEmail) weaknesses.push("No email address detected — add a professional email at the top.");
  if (!hasPhone) weaknesses.push("No phone number detected — recruiters need a way to contact you.");
  if (!hasLinkedIn && !hasGithub) weaknesses.push("No LinkedIn or GitHub link — add at least one to showcase your profile/work.");
  if (!hasSummary) weaknesses.push("No summary/objective section — add 2-3 lines tailored to the target role.");
  if (!hasExperience) weaknesses.push("No experience/employment section detected — add internships, jobs, or freelance work.");
  if (!hasProjects) weaknesses.push("No projects section — projects are the strongest proof of skills for freshers.");
  if (!hasEducation) weaknesses.push("Education section not clearly detected — ensure degree, college, and year are listed.");
  if (!hasSkillsSection) weaknesses.push("No dedicated skills section — ATS parsers look for one; add a 'Technical Skills' section.");
  if (actionVerbCount < 4) weaknesses.push(`Only ${actionVerbCount} action verbs found — rewrite bullets starting with strong verbs (Built, Developed, Improved…).`);
  if (quantified < 2) weaknesses.push("Few quantified achievements — add numbers (%, users, time saved, accuracy) to bullets.");
  if (wordCount < 250) weaknesses.push(`Resume is short (${wordCount} words) — add more depth: projects, achievements, and skills.`);
  if (wordCount > 1000) weaknesses.push(`Resume is long (${wordCount} words) — trim to 1-2 pages; cut filler and repetition.`);
  if (weaknesses.length === 0) weaknesses.push("No major structural gaps detected — focus on tailoring keywords to each job posting.");
  const suggestions: string[] = [];
  if (missingSkills.length > 0) suggestions.push(`Add ${missingSkills.slice(0, 4).join(", ")} to your resume — learn them via the roadmap below and add a project proving each one.`);
  if (!hasSummary) suggestions.push("Write a 2-3 line professional summary mirroring the job title and top 3 skills from the JD.");
  if (!hasProjects) suggestions.push("Add a Projects section with 2-3 projects: name, tech stack, 2 bullets with outcomes, and GitHub/demo links.");
  if (quantified < 2) suggestions.push("Quantify every bullet: e.g., 'Reduced load time by 40%', 'Trained on 10k records', 'Served 500+ users'.");
  if (actionVerbCount < 4) suggestions.push("Start each bullet with a strong action verb: Developed, Built, Optimized, Led, Automated, Deployed…");
  if (!hasLinkedIn && !hasGithub) suggestions.push("Create/optimize LinkedIn and GitHub profiles; link them in the resume header.");
  if (!hasSkillsSection) suggestions.push("Add a 'Technical Skills' section grouped by category (Languages, Frameworks, Tools, Databases).");
  if (wordCount > 1000) suggestions.push("Trim to 1-2 pages: remove old/irrelevant bullets, combine similar points, use concise phrasing.");
  if (wordCount < 250) suggestions.push("Expand with a Projects section, certifications, and detailed achievement bullets to reach ~400-600 words.");
  suggestions.push("Mirror the exact keywords from the job description (tools, frameworks, responsibilities) — ATS matches literal terms.");
  suggestions.push("Save as PDF with selectable text (not a scanned image) so ATS parsers can read it — this app already handles that.");
  suggestions.push("Tailor a fresh copy of your resume for every application; re-run this analyzer to track score improvements.");
  const interviewQuestions = buildInterviewQuestions(jobTitle, skillsPresent, missingSkills, jdSkills);
  const roadmap: RoadmapItem[] = missingSkills.slice(0, 8).map((skill) => {
    const cat = COURSE_CATALOG[skill] || genericCourse(skill);
    return {
      skill,
      level: cat.level,
      duration: cat.duration,
      course: cat.course,
      topics: cat.topics,
      weekPlan: buildWeekPlan(skill, cat.duration, cat.topics),
    };
  });
  return {
    matchScore,
    atsScore,
    skillsPresent,
    missingSkills,
    strengths,
    weaknesses,
    suggestions,
    interviewQuestions,
    roadmap,
    wordCount,
    keywordOverlap: Math.round(keywordOverlap * 100),
    skillsCoverage: Math.round(skillsCoverage * 100),
  };
}
